import{z as o,x as t,o as e,c as s,q as B,j as l,D as a,d as r,s as A,S as i}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"退火与数据课程","description":"","frontmatter":{"title":"退火与数据课程","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pf2-annealing-curriculum.md","filePath":"llm/pf2-annealing-curriculum.md","lastUpdated":1791063341000}'),p={name:"llm/pf2-annealing-curriculum.md"};function m(d,E,D,u,h,_){const n=t("Mermaid");return e(),s("div",null,[E[2]||(E[2]=B('<h1 id="退火与数据课程" tabindex="-1">退火与数据课程 <a class="header-anchor" href="#退火与数据课程" aria-label="Permalink to &quot;退火与数据课程&quot;">​</a></h1><div class="epigraph"><p>退火从来不是单纯的降温：学习率降下去的同时，数据要换上来——温度与测度是同一阶段的两根轴。</p><footer>—— 据 OLMo 2（arXiv:2501.00656）与 Llama 3、MiniCPM 的退火段配方整理</footer></div><p><a href="/llm/pf2-data-exhaustion">上一课</a>处理的是计划外的数据缺口；本课进入收束单元，写计划内的最后一段：退火期把学习率降到零，同时把数据测度切向高质量混合。<a href="/llm/annealing-phase">退火阶段</a>与<a href="/llm/anneal-mixture">退火混合</a>两课已分别写过温度轴与数据轴；本课把两轴合回一个阶段配方，并厘清它与 OLMo 2 式中训的谱系关系。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把退火只当温度处理会白烧这一段：学习率降下来只是让更新变细，末期的高质量数据若不换上来，降温只是在幂律尾巴上多磨掉一点 CE——该补的能力补不上。反过来，只换数据不降温也不行：高温下大步长会把细粒度的知识抖散，学不深。两根轴要同时动，这就是为什么退火是「阶段」而不是「日程的最后一段」：它有自己的混合、自己的检查点策略、自己的评测点。另一个易错点是把它与 SFT 混淆——退火换的是预训练测度，仍是下一词预测，不引入对话模板。</p><h3 id="阶段配方" tabindex="-1">阶段配方 <a class="header-anchor" href="#阶段配方" aria-label="Permalink to &quot;阶段配方&quot;">​</a></h3><p>退火占算力预算的末段，通常只占约百分之五到十的 FLOPs，却消耗配方里最精的数据。温度轴：从峰值段平滑降到近零，寿命与主干计划绑定。数据轴：\\(w_{\\mathrm{anneal}}\\) 抬高质量源——数学、代码、教科书风、长上下文——守住<a href="/llm/decontamination-pipeline">去污</a>与语种字符预算，与主干混合用插值衔接而不是硬切。产物轴：OLMo 2 的做法是把这一段与「中训」叠在同一短阶段——预训练检查点加 Dolmino 混合加线性降到零，并从<strong>多个数据顺序</strong>各收一个点做 souping，见<a href="/llm/olmo2-midtrain-recipe">中训配方</a>与<a href="/llm/model-soups-averaging">模型汤</a>。</p><p><span class="marginnote">数字实例：一个计划吃 1 万亿 token 的 run，退火段按 5%–10% 算只有 500–1000 亿 token；但这段的混合里数学、代码、教科书风的占比往往抬到全 run 数倍——用十分之一的算力买进配方里最精的数据，这就是「末段小、含金量高」的账。</span></p>',8)),(e(),l(i,null,{default:a(()=>[A(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E4%B8%BB%E5%B9%B2%E9%98%B6%E6%AE%B5%EF%BC%9A%E5%B3%B0%E5%80%BC%E5%AD%A6%E4%B9%A0%E7%8E%87%20%2B%20%E9%9D%99%E6%80%81%E9%85%8D%E6%AF%94%22%5D%20--%3E%20A%5B%22%E9%80%80%E7%81%AB%E6%AE%B5%E5%BC%80%E5%A7%8B%22%5D%0A%20%20A%20--%3E%20T%5B%22%E6%B8%A9%E5%BA%A6%E8%BD%B4%EF%BC%9A%E5%B9%B3%E6%BB%91%E9%99%8D%E5%88%B0%E8%BF%91%E9%9B%B6%22%5D%0A%20%20A%20--%3E%20D%5B%22%E6%95%B0%E6%8D%AE%E8%BD%B4%EF%BC%9A%E6%8F%92%E5%80%BC%E5%88%87%E5%90%91%E9%AB%98%E8%B4%A8%E9%87%8F%E6%B7%B7%E5%90%88%22%5D%0A%20%20T%20--%3E%20P%5B%22%E5%90%84%E6%95%B0%E6%8D%AE%E9%A1%BA%E5%BA%8F%E5%90%84%E6%94%B6%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%0A%20%20D%20--%3E%20P%0A%20%20P%20--%3E%20SO%5B%22%E5%A4%9A%E8%B7%AF%20souping%20%E5%87%BA%E5%80%99%E9%80%89%22%5D%0A%20%20SO%20--%3E%20NEXT%5B%22%E8%BF%9B%E5%90%8E%E8%AE%AD%E7%BB%83%20%2F%20%E8%AF%84%E6%B5%8B%E9%97%A8%E7%A6%81%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>落地四条。第一，<strong>插值衔接</strong>：混合切换按 token 平滑过渡，硬切会在切换点留下可见的损失台阶，让之后的归因都多一个混杂变量。第二，<strong>与检查点同表</strong>：退火段加密收点，每个点的（学习率、混合、token 位置）三元组与检查点同存——选点一课的候选池就来自这里。第三，<strong>评测对齐</strong>：退火后的模型才与最终评测可比；拿主干未退火的点去打别人退火后的分数，是比较事故。第四，** Souping 纪律**：多路汤的成员必须共享同一预训练起点、只差数据顺序或短阶段混合；验证集拒远点，防一碗夹生汤。</p><p><span class="marginnote">退火段补数学与代码靠的是换混合而不是降温本身：单看温度轴，退火后训练 CE 只降一截；OLMo 2 的中训把平均分抬了约十分，主要记在 Dolmino 混合与新能力源上——「cooldown 会自动整理出能力」是这一课最常见的误读。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么两轴必须同时动：学习率决定每个样本被「写」的深度，测度决定写什么。高温写深但糙，适合粗结构；低温写浅但稳，适合把已经成形的能力整理、把高质量样本的细节刻进去。单独动任何一轴都在浪费另一半的功。为什么与中训合并在一个短阶段：两者共同点是「低学习率下的能力注入」，分开做会付出两次交接成本；合并后一次降温支撑多份数据分叉，每个分叉都便宜到可以消融。为什么插值优于硬切：梯度预算的转移是连续量，模型对测度的突变没有准备——台阶本身无害，但它是免费的混杂变量。</p>',5)),(e(),l(i,null,{default:a(()=>[A(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%94%B6%E6%9D%9F%E6%AE%B5%E6%80%8E%E4%B9%88%E5%AE%89%E6%8E%92%E4%B8%A4%E6%A0%B9%E8%BD%B4%22%5D%20--%3E%20ONLY_T%5B%22%E5%8F%AA%E9%99%8D%E6%B8%A9%EF%BC%9A%E6%B7%B7%E5%90%88%E4%B8%8D%E5%8F%98%22%5D%0A%20%20ONLY_T%20--%3E%20T1%5B%22%E6%9B%B4%E6%96%B0%E5%8F%98%E7%BB%86%EF%BC%8C%E4%BD%86%E6%8D%A2%E4%B8%8D%E4%B8%8A%E6%96%B0%E8%83%BD%E5%8A%9B%22%5D%0A%20%20T1%20--%3E%20T2%5B%22CE%20%E5%8F%AA%E5%9C%A8%E5%B9%82%E5%BE%8B%E5%B0%BE%E5%B7%B4%E4%B8%8A%E5%A4%9A%E7%A3%A8%E4%B8%80%E7%82%B9%22%5D%0A%20%20Q%20--%3E%20ONLY_D%5B%22%E5%8F%AA%E6%8D%A2%E6%95%B0%E6%8D%AE%EF%BC%9A%E6%B8%A9%E5%BA%A6%E4%B8%8D%E9%99%8D%22%5D%0A%20%20ONLY_D%20--%3E%20D1%5B%22%E5%A4%A7%E6%AD%A5%E9%95%BF%E6%8A%8A%E7%BB%86%E8%8A%82%E7%9F%A5%E8%AF%86%E6%8A%96%E6%95%A3%22%5D%0A%20%20D1%20--%3E%20D2%5B%22%E9%AB%98%E8%B4%A8%E9%87%8F%E6%A0%B7%E6%9C%AC%E5%AD%A6%E4%B8%8D%E6%B7%B1%22%5D%0A%20%20T1%20--%3E%20BOTH%5B%22%E4%B8%A4%E8%BD%B4%E5%90%8C%E5%8A%A8%EF%BC%9A%E4%BD%8E%E6%B8%A9%E5%86%99%E5%BE%97%E7%A8%B3%20%2B%20%E5%A5%BD%E6%95%B0%E6%8D%AE%E5%86%99%E5%BE%97%E5%87%86%22%5D%0A%20%20D2%20--%3E%20BOTH%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">直觉类比：学习率像刻刀的下刀力度，数据混合像刻的图样。力度大适合开粗坯，力度小适合修细节；只换精细图样还用大开大合的力度，细节全被震掉；只减力度不换图样，刀再稳也刻不出新内容——两根轴必须一起动。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课的阶段配方不覆盖 SFT 与 RLHF：退火不换目标函数，不引入模板；交接给后训练的口径是候选模型加证据，见<a href="/llm/continued-pretraining">继续预训练</a>对 mid-training 命名的讨论。序列长度的阶段化（先短后长）是训练中段的结构课程，见<a href="/llm/sequence-length-warmup">序列长度预热</a>，退火期把长上下文抬进混合只是数据轴的一个分量。多路 souping 的统计细节与拒远点判据在选点一课展开。最后，短预算下这一段可以做成本可实验的接口——多混合多顺序各跑一次退火再选优；预算大时它收敛为一次，接口形态不变。</p><p><span class="marginnote">常见误区：以为退火段越长越好。它吃的是最贵的精数据，把退火拉长等于拿「细修」当「主修」烧预算；主干阶段该打的粗结构没打完，退火再长也补不回来——5%–10% 的配额是成本权衡，不是随手写的技术细节。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>退火是双轴阶段：温度降到近零与测度切向高质量混合必须同时做。</li><li>占约 5%–10% FLOPs；混合用插值衔接，守去污与语种预算。</li><li>与中训同构：低学习率下注入能力源，多数据顺序收点做 souping。</li><li>退火后的点才与最终评测可比；cooldown 不自动产生能力。</li><li>出处：OLMo 2（arXiv:2501.00656）；Grattafiori et al., Llama 3；Hu et al., MiniCPM。</li></ul>',6))])}const T=o(p,[["render",m]]);export{f as __pageData,T as default};
